head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > maxlength]<br/>Textarea 컴포넌트에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "한 문자의 길이를 1 로 계산(다국어 포함)하여 입력 가능한 최대 길이를 숫자로 설정합니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 입력을 제한하지 않습니다.",
        "최대 길이를 초과하면 초과분이 자동으로 잘립니다.",
        "maxByteLength 와 maxlength 를 모두 설정하면 설정값이 작은 속성이 적용됩니다.",
        "maxByteLength 와 maxlength 를 모두 설정 시 같은 값이면 maxByteLength 가 적용됩니다.",
        "validate() 메소드 실행 시 입력값이 설정값보다 크면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "validate() 시스템 기본 메시지는 'n자를 초과하여 입력할 수 없습니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function (target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (maxlength=5, 'abcdefg'(7자) 입력 → 'abcde'(5자) 초과분 자동 자르기)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("abcdefg");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}


// target2 (maxlength 미설정 → 입력 제한 없음, '-1' 로 동작)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("abcdefghijklmnop");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}


// target3 (maxlength=5, 다국어 한글 입력 → 한 문자=1 로 계산, '가나다라마' 5자 적용)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다라마바사");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
}


// target4 (maxByteLength=10 + maxlength=3 → 작은값(maxlength=3) 적용, 기대값='가나다'(3자))
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("가나다라마");
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
}


// target5 (maxByteLength=6 + maxlength=3, 한글 3자 → 두 한도 동일 (한글 3자=6byte, maxlength 3자), 같은 값이면 maxByteLength 적용)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가나다라");
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5);
}


// target6 (maxlength=5, displaymessage=true, invalidMessage 설정 → validate 실패 시 사용자 메시지 출력)
// setValue 후 즉시 validate() 호출 시 oneditend 미발생으로 잘림 미적용 → 길이 초과로 FAIL 발생
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("abcdefg");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}


// target7 (maxlength=5, displaymessage=true, invalidMessage/invalidMessageFunc 미설정 → 시스템 기본 메시지)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("abcdefg");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}


// target8 (maxlength=5, displaymessage=true, invalidMessageFunc 설정 → 사용자 정의 함수 메시지 출력)
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("abcdefg");
};

scwin.btn_validate8_onclick = function (e) {
    scwin.btn_setValue8_onclick();
    scwin.check_validate(target8);
}


// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidType = this.getType();
    let invalidValue = this.getValue();
    let msg = "Not valid.";

    if (invalidType === "maxlength") {
        msg = "사용자 정의 메시지: 최대 " + invalidValue + " 자리 초과";
    }
    return msg;
}
